func (v AttributesValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	values := types.ListValueMust(
		ValuesType{
			basetypes.ObjectType{
				AttrTypes: ValuesValue{}.AttributeTypes(ctx),
			},
		},
		v.Values.Elements(),
	)

	if v.Values.IsNull() {
		values = types.ListNull(
			ValuesType{
				basetypes.ObjectType{
					AttrTypes: ValuesValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Values.IsUnknown() {
		values = types.ListUnknown(
			ValuesType{
				basetypes.ObjectType{
					AttrTypes: ValuesValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var objectTypesVal basetypes.ListValue
	switch {
	case v.ObjectTypes.IsUnknown():
		objectTypesVal = types.ListUnknown(types.StringType)
	case v.ObjectTypes.IsNull():
		objectTypesVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		objectTypesVal, d = types.ListValue(types.StringType, v.ObjectTypes.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"description": basetypes.StringType{},
			"key":         basetypes.StringType{},
			"multiselect": basetypes.BoolType{},
			"name":        basetypes.StringType{},
			"object_types": basetypes.ListType{
				ElemType: types.StringType,
			},
			"status": basetypes.StringType{},
			"type":   basetypes.StringType{},
			"values": basetypes.ListType{
				ElemType: ValuesValue{}.Type(ctx),
			},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"description": basetypes.StringType{},
		"key":         basetypes.StringType{},
		"multiselect": basetypes.BoolType{},
		"name":        basetypes.StringType{},
		"object_types": basetypes.ListType{
			ElemType: types.StringType,
		},
		"status": basetypes.StringType{},
		"type":   basetypes.StringType{},
		"values": basetypes.ListType{
			ElemType: ValuesValue{}.Type(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"description":  v.Description,
			"key":          v.Key,
			"multiselect":  v.Multiselect,
			"name":         v.Name,
			"object_types": objectTypesVal,
			"status":       v.Status,
			"type":         v.AttributesType,
			"values":       values,
		})

	return objVal, diags
}

func (v AttributesValue) Equal(o attr.Value) bool {
	other, ok := o.(AttributesValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Key.Equal(other.Key) {
		return false
	}

	if !v.Multiselect.Equal(other.Multiselect) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.ObjectTypes.Equal(other.ObjectTypes) {
		return false
	}

	if !v.Status.Equal(other.Status) {
		return false
	}

	if !v.AttributesType.Equal(other.AttributesType) {
		return false
	}

	if !v.Values.Equal(other.Values) {
		return false
	}

	return true
}

